INSERT INTO events (id, city_id, venue_id, title, pitch, description, starts_at, ends_at, address, neighborhood, lat, lng, getting_there, door_price, ticket_url, policy_tags, scenes, status, is_sample) VALUES ('wyxr-b76c4dae', 'memphis', 'venue-satellite', 'WYXR''s Raised By Sound Fest - Soccer Mommy w/Late Night Cardigan', 'WYXR presents', 'Soccer Mommy Dubbed by Rolling Stone as “one of Indie Rock’s most beloved singer-songwriters,” Swiss-born and Nashville-based Soccer Mommy (Sophie Allison) has built a loyal following with her plaintive, confessional storytelling suffused with indie pop/rock sensibilities. WYXR is elated to have her headline the first Friday night Raised By Sound Fest show. Late Night Cardigan For those who love biting lyrics and soaring power-pop anthems, Late Night Cardigan is Memphis’ worst kept secret. WYXR has been a fan for years, and you will be too. Look for a new album this fall “One Million Dollars” then catch them on the big stage at the brand new Satellite Music Hall in support of Soccer Mommy and WYXR. WYXR’s Raised By Sound Fest celebrates Memphis music, new and old, across multiple genres and features our unique group of volunteer DJs. It will feature free, day-long performances on Saturday, a ticketed headline concert on Friday, and a ticketed headline concert and after-party on Saturday night.
