INSERT INTO events (id, city_id, venue_id, title, pitch, description, starts_at, ends_at, address, neighborhood, lat, lng, getting_there, door_price, ticket_url, policy_tags, scenes, status, is_sample) VALUES ('wyxr-cb0c9f81', 'memphis', 'venue-crosstown-arts', 'WYXR''s Raised By Sound Fest - Wednesday, Patterson Hood, Sylvan Esso DJ Set, Hand Habits, Chanel Beads and more!', 'WYXR presents', 'Wednesday (solo) + Patterson Hood Two Southern storytelling powerhouses join forces for an intimate set to raise funds for WYXR. It’s only fitting that they co-headline the station’s biggest fundraiser since they’re the embodiment of the independent and unconventional spirit of WYXR. This will be the first full show featuring Karly Hartzman (Wednesday) and Patterson Hood (Drive-By Truckers) and it’s sure to be heavy on the Memphis love (they’ve performed Big Star and Chris Bell tunes live) and light on the formality. Don’t miss it. East Atrium Sylvan Esso DJ Set Saturday, Dec. 5 Doors 8:30 pm – Show 9 – 11 pm You might know Sylvan Esso (Amelia Meath and Nick Sanborn) by their catchy, electro-pop tunes, most recently their incredible new album Ow ∞. The two have also been making waves as a DJ duo with discerning Reddit users describing their DJ sets as “nonstop, absolute riots” and “great bangers back to back.” This will be their first performance in Memphis in what’s quickly become a can’t-miss, fan favorite at the fest. Your after-party ticket gets you complimentary food by Go-Time Group (Fawn, Cameo, Mary’s B.O.T.E., No Comment), wine, beer, cocktails, art experiences and more. Your VIP ticket to Saturday’s headline show of Wednesday (solo) and Patterson Hood includes after party access. Central & East Atrium Spend the day at Raised By Sound Fest for free live music from 1 to 6:30 pm along with community tables featuring local organizations lifting up the arts, animal rescue, music and much more. Family and dog friendly! 5:15 pm Central Atrium Chanel Beads An experimental dream pop project by New York-based Shane Levers, Chanel Beads makes their first appearance in Memphis at Raised By Sound Fest. Their June 2026 sophomore album, Your Day Will Come (same title as their first album), earned praise from renowned Indie Music staples NME, Pitchfork and Paste. 3:55 pm East Atrium Hand Habits WYXR is elated to present the Memphis debut of Hand Habits, aka Meg Duffy. Their contributions to collaboration and community in the Indie music world are right in line with WYXR. Along with their incredible solo project, Hand Habits, they’ve brought their immense swiss-army-like talents (vocals, keys, bass, guitar, slide) and vision to work by Kevin Morby, The War on Drugs, Perfume Genius, and more. 2:50 pm East Atrium Out On The Eaves The current creative venture by Memphis mainstay, Patrick Carey, is a stunning display of psychedelic folk and pop. Patrick cut his teeth in Athens, Georgia, but since landing in Memphis, has become embedded in the local arts scene and has released two exceptional albums as Out On The Eaves. His 2026 release, With No Reflection, is a revelation and was launched at a release party with none other than Bonnie “Prince” Billy. 2 pm Central Atrium Marcella Simien + Qemist On their own, Marcella and Qemist are beloved, prolific and ground-breaking Memphis artists. Together, their powers double. Swamp Soul Queen Marcella’s transcendent vocals soar over Qemist’s infectious, perfectly layered beats and melodies. It’s something to behold. This is the first performance of its kind, with visual and stylistic surprises in store. 1 pm Central Atrium Blue Tom Revue The only performance that’s kicked off Raised By Sound Fest since the very beginning. These young artists historically go on to BIG things – including spots at RIVERBEAT and Mempho Fest. It’s your chance to see the future of Memphis music for free – and you can say “I saw them when . . .”
